INSERT INTO questions (question_id, subject_id, created_by, question_text, question_type, difficulty, default_marks, model_answer, status, created_at) VALUES
(1,1,2,'Which normal form removes partial dependencies on a composite key?','MCQ','EASY',2,NULL,'ACTIVE','2026-07-02 10:00:00'),
(2,1,2,'Which SQL clause filters groups after aggregation?','MCQ','EASY',2,NULL,'ACTIVE','2026-07-03 10:00:00'),
(3,1,2,'Which isolation level prevents dirty reads but allows non-repeatable reads?','MCQ','MEDIUM',2,NULL,'ACTIVE','2026-07-04 10:00:00'),
(4,1,2,'A foreign key primarily enforces:','MCQ','EASY',2,NULL,'ACTIVE','2026-07-05 10:00:00'),
(5,1,2,'Which index type does InnoDB use by default?','MCQ','MEDIUM',2,NULL,'ACTIVE','2026-07-01 10:00:00'),
(6,1,2,'A table can have more than one PRIMARY KEY constraint.','TRUE_FALSE','EASY',1,NULL,'ACTIVE','2026-07-02 10:00:00'),
(7,1,2,'ROLLBACK undoes all changes made since the last COMMIT in a transaction.','TRUE_FALSE','EASY',1,NULL,'ACTIVE','2026-07-03 10:00:00'),
(8,1,2,'Define a candidate key and give one example.','SHORT','MEDIUM',3,'A minimal set of attributes that uniquely identifies a row, e.g. enrollment_no in student_profiles.','ACTIVE','2026-07-04 10:00:00'),
(9,1,2,'Explain the ACID properties of a transaction with a banking example.','DESCRIPTIVE','HARD',5,'Atomicity: transfer fully happens or not. Consistency: balances stay valid. Isolation: concurrent transfers do not interfere. Durability: committed transfer survives a crash.','ACTIVE','2026-07-05 10:00:00'),
(10,2,3,'Worst-case time complexity of binary search on a sorted array is:','MCQ','EASY',2,NULL,'ACTIVE','2026-07-01 10:00:00'),
(11,2,3,'Which data structure uses LIFO order?','MCQ','EASY',2,NULL,'ACTIVE','2026-07-02 10:00:00'),
(12,2,3,'Which traversal of a BST yields keys in sorted order?','MCQ','MEDIUM',2,NULL,'ACTIVE','2026-07-03 10:00:00'),
(13,2,3,'Which algorithm finds shortest paths with non-negative edge weights?','MCQ','MEDIUM',2,NULL,'ACTIVE','2026-07-04 10:00:00'),
(14,2,3,'Average-case time complexity of quicksort is:','MCQ','MEDIUM',2,NULL,'ACTIVE','2026-07-05 10:00:00'),
(15,2,3,'A min-heap guarantees the root is the smallest element.','TRUE_FALSE','EASY',1,NULL,'ACTIVE','2026-07-01 10:00:00'),
(16,2,3,'Merge sort is an in-place sorting algorithm.','TRUE_FALSE','MEDIUM',1,NULL,'ACTIVE','2026-07-02 10:00:00'),
(17,2,3,'State the difference between an array and a linked list.','SHORT','EASY',3,'Arrays give O(1) random access with contiguous memory; linked lists allow O(1) insertion given a node but need O(n) access.','ACTIVE','2026-07-03 10:00:00'),
(18,2,3,'Describe how a hash table handles collisions using chaining and open addressing.','DESCRIPTIVE','HARD',5,'Chaining stores colliding keys in a list per bucket; open addressing probes for another free slot (linear, quadratic, double hashing).','ACTIVE','2026-07-04 10:00:00'),
(19,3,4,'Which scheduling algorithm can cause starvation of long processes?','MCQ','MEDIUM',2,NULL,'ACTIVE','2026-07-05 10:00:00'),
(20,3,4,'A deadlock requires all of these EXCEPT:','MCQ','MEDIUM',2,NULL,'ACTIVE','2026-07-01 10:00:00'),
(21,3,4,'Which memory management technique can cause external fragmentation?','MCQ','MEDIUM',2,NULL,'ACTIVE','2026-07-02 10:00:00'),
(22,3,4,'A semaphore with initial value 1 is typically used as a:','MCQ','EASY',2,NULL,'ACTIVE','2026-07-03 10:00:00'),
(23,3,4,'Which is NOT a process state?','MCQ','EASY',2,NULL,'ACTIVE','2026-07-04 10:00:00'),
(24,3,4,'A thread shares the address space of its parent process.','TRUE_FALSE','EASY',1,NULL,'ACTIVE','2026-07-05 10:00:00'),
(25,3,4,'Belady''s anomaly can occur with the LRU page replacement policy.','TRUE_FALSE','HARD',1,NULL,'ACTIVE','2026-07-01 10:00:00'),
(26,3,4,'What is a context switch?','SHORT','EASY',3,'Saving the state of the running process and loading the state of another so the CPU can be reallocated.','ACTIVE','2026-07-02 10:00:00'),
(27,3,4,'Compare paging and segmentation.','DESCRIPTIVE','MEDIUM',5,'Paging uses fixed-size frames and avoids external fragmentation; segmentation uses logical variable-size units matching program structure.','ACTIVE','2026-07-03 10:00:00'),
(28,1,2,'Which SQL keyword removes duplicate rows from a result set?','MCQ','EASY',2,NULL,'ARCHIVED','2026-07-03 10:00:00');
